"""JSON Lines import and atomic, validated export for ledger records."""

import json

from ledgerfmt.model import record_from_wire, record_to_wire


def load(stream):
    """Read one wire object per nonblank line, reporting physical line numbers."""
    records = []
    for line_number, line in enumerate(stream, 1):
        if not line.strip():
            continue
        try:
            wire = json.loads(line)
            if not isinstance(wire, dict) or set(wire) != {"account", "amount", "tags"}:
                raise ValueError("expected an object with exactly account, amount, tags")
            records.append(record_from_wire(**wire))
        except ValueError as error:
            raise ValueError(f"JSONL line {line_number}: {error}") from error
    return records


def dump(records, stream):
    """Serialize every record before making any write to the caller's stream."""
    lines = []
    for row_number, record in enumerate(records, 1):
        try:
            wire = record_to_wire(record)
            lines.append(json.dumps(wire, sort_keys=True, ensure_ascii=False) + "\n")
        except (ValueError, TypeError) as error:
            raise ValueError(f"JSONL row {row_number}: {error}") from error
    stream.write("".join(lines))

