"""CSV ledger import and atomic, validated export."""

import csv
import io
import json

from ledgerfmt.model import record_from_wire, record_to_wire


_HEADER = ["account", "amount", "tags"]


def load(stream):
    """Read the exact header and three-field records using strict CSV parsing."""
    reader = csv.reader(stream, strict=True)
    records = []
    row_number = 1
    try:
        if next(reader, None) != _HEADER:
            raise ValueError("CSV row 1: expected header account,amount,tags")
        row_number = 2
        for row in reader:
            try:
                if len(row) != 3:
                    raise ValueError(f"expected 3 fields, got {len(row)}")
                account, amount, tags = row
                records.append(record_from_wire(account, amount, json.loads(tags)))
            except ValueError as error:
                raise ValueError(f"CSV row {row_number}: {error}") from error
            row_number += 1
    except csv.Error as error:
        raise ValueError(
            f"CSV row {row_number} (line {reader.line_num}): {error}"
        ) from error
    return records


def dump(records, stream):
    """Buffer the header and all serialized rows before writing the output."""
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    writer.writerow(_HEADER)
    for row_number, record in enumerate(records, 2):
        try:
            wire = record_to_wire(record)
            account = wire["account"]
            fields = [wire["amount"], json.dumps(wire["tags"], ensure_ascii=False)]
            # With LF terminators csv.writer does not quote a bare CR, although
            # csv.reader treats it as a record boundary. Quote that account cell
            # explicitly; this branch cannot contain any quotes needing escape.
            if "\r" in account and not any(char in account for char in ',"\n'):
                buffer.write('"' + account + '",')
                writer.writerow(fields)
            else:
                writer.writerow([account, *fields])
        except (ValueError, TypeError, csv.Error) as error:
            raise ValueError(f"CSV row {row_number}: {error}") from error
    stream.write(buffer.getvalue())

