"""JSON Lines import and export for ledger records."""

import json

from ledgerfmt.model import record_from_wire, record_to_wire


_FIELDS = {"account", "amount", "tags"}


def load(stream):
    """Load nonblank JSON object lines from a text stream."""
    records = []
    for line_number, line in enumerate(stream, start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except (json.JSONDecodeError, TypeError, ValueError) as error:
            raise ValueError(f"line {line_number}: malformed JSON: {error}") from error

        if not isinstance(value, dict):
            raise ValueError(f"line {line_number}: expected a JSON object")
        if set(value) != _FIELDS:
            raise ValueError(
                f"line {line_number}: expected exactly account, amount, and tags fields"
            )
        try:
            record = record_from_wire(value["account"], value["amount"], value["tags"])
        except (ValueError, TypeError, KeyError) as error:
            raise ValueError(f"line {line_number}: invalid record: {error}") from error
        records.append(record)
    return records


def dump(records, stream):
    """Validate and serialize records before writing JSON Lines to a text stream."""
    serialized = []
    try:
        iterator = iter(records)
    except TypeError as error:
        raise ValueError("row 1: records must be iterable") from error

    for row_number, record in enumerate(iterator, start=1):
        try:
            wire = record_to_wire(record)
            line = json.dumps(wire, ensure_ascii=False, sort_keys=True)
        except (ValueError, TypeError, KeyError) as error:
            raise ValueError(f"row {row_number}: invalid record: {error}") from error
        serialized.append(line)

    if serialized:
        stream.write("".join(line + "\n" for line in serialized))

